def banco_enmiendas():
    S = [(t("The police want to search your home without a warrant.", "La policía quiere registrar su casa sin orden judicial."), 4, [1, 8], t("Searches need a warrant based on probable cause.", "Para registrar hace falta una orden basada en causa probable.")),
         (t("You are accused of a serious crime and cannot pay a lawyer.", "Le acusan de un delito grave y no puede pagar un abogado."), 6, [5, 8], t("The right to a lawyer is one of the trial guarantees.", "El derecho a abogado es una de las garantías del juicio.")),
         (t("A group protests peacefully in a plaza, asking for a change.", "Un grupo se manifiesta pacíficamente en una plaza para pedir un cambio."), 1, [9, 10], t("Assembly and petition are in the First.", "La reunión y la petición están en la Primera.")),
         (t("You were tried and found not guilty, and now the prosecutor wants to try you again for the same crime.", "Le juzgaron y le absolvieron, y ahora el fiscal quiere juzgarle otra vez por lo mismo."), 5, [6, 8], t("No double jeopardy: the Fifth.", "Nada de doble enjuiciamiento: la Quinta.")),
         (t("The government needs your land for a highway and wants to take it.", "El gobierno necesita su terreno para una carretera y quiere expropiarlo."), 5, [4, 10], t("It can, but only for public use and with just compensation.", "Puede hacerlo, pero solo para uso público y con una compensación justa.")),
         (t("A judge sets a huge bail for a minor offense.", "Un juez fija una fianza desproporcionada por una infracción menor."), 8, [6, 4], t("No excessive bail or fines.", "Ni fianzas ni multas excesivas.")),
         (t("You want to publish a newspaper that criticizes the mayor.", "Quiere publicar un periódico que critica al alcalde."), 1, [4, 9], t("Freedom of the press protects criticism of those in power.", "La libertad de prensa protege la crítica al poder.")),
         (t("In peacetime, the government wants to house soldiers in your home.", "En tiempo de paz, el gobierno pretende alojar soldados en su casa."), 3, [2, 4], t("The least-used amendment today; in 1791 the colonists had just lived it.", "Es la enmienda menos usada hoy; en 1791 los colonos acababan de vivirlo.")),
         (t("You have a civil lawsuit over money and want a jury to decide it.", "Tiene un pleito civil por dinero y quiere que lo decida un jurado."), 7, [6, 5], t("The Seventh extends juries to civil cases.", "La Séptima extiende el jurado a los pleitos civiles.")),
         (t("A state requires you to pay a tax before you can vote in a federal election.", "Un estado le exige pagar un impuesto para poder votar en una elección federal."), 24, [15, 19], t("The poll tax was banned in federal elections in 1964.", "El impuesto electoral se prohibió en las elecciones federales en 1964.")),
         (t("You want to own and carry a firearm.", "Quiere poseer y portar un arma de fuego."), 2, [3, 10], t("The Second recognizes this right; courts have long argued over its exact reach.", "La Segunda reconoce este derecho; los tribunales llevan décadas discutiendo su alcance exacto.")),
         (t("You claim a right that does not appear on any list in the Constitution.", "Alega un derecho que no aparece en ninguna lista de la Constitución."), 9, [10, 1], t("Listing some rights does not deny the others.", "Enumerar algunos derechos no significa negar los demás."))]
    return [{"enun": "<strong>" + s + "</strong><br>" + t("Which amendment protects you?", "¿Qué enmienda le protege?"), "ops": [enm(ok)] + [enm(x) for x in otras], "ok": 0, "exp": "<strong>" + enm(ok) + ".</strong> " + e} for s, ok, otras, e in S]


def casos_lib():
    G = [t("Civil liberty", "Libertad civil"), t("Civil right", "Derecho civil")]
    PL = t("Is someone asking the government to stop doing something?", "¿Se pide que el gobierno deje de hacer algo?")
    PR = t("Is someone asking for equal treatment?", "¿Se pide un trato igual?")
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("Sort each situation by the direction of the protection.", "Clasifique cada situación por la dirección de la protección."), "grupos": G, "etiqueta": t("This is a…", "Esto es…"),
                "piezas": [{"t": a, "v": v, "pista": [PL, PR][v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("The police may not search a car without probable cause.", "La policía no puede registrar un auto sin causa probable."), 0), (t("A restaurant may not refuse to serve customers because of their race.", "Un restaurante no puede negarse a atender a clientes por su raza."), 1),
                                      (t("A person may stay silent instead of testifying against himself.", "Una persona puede guardar silencio en lugar de declarar contra sí misma."), 0), (t("A building open to the public must be accessible to people who use wheelchairs.", "Un edificio abierto al público debe ser accesible para quienes usan silla de ruedas."), 1)]),
        caso(t("Set 2", "Serie 2"), [(t("A city may not ban a newspaper for criticizing the mayor.", "Una ciudad no puede prohibir un periódico por criticar al alcalde."), 0), (t("Women and men doing the same job must receive equal pay.", "Las mujeres y los hombres que hacen el mismo trabajo deben recibir el mismo salario."), 1),
                                      (t("The government may not choose an official religion.", "El gobierno no puede elegir una religión oficial."), 0), (t("A state may not keep citizens from voting because of their race.", "Un estado no puede impedir votar a sus ciudadanos por su raza."), 1)]),
    ]


def casos_orden():
    return [{"titulo": t("The expansion of the vote", "La expansión del voto"), "intro": t("Put the six steps in order with ▲ and ▼.", "Ordene los seis pasos con ▲ y ▼."),
             "pasos": [t("The Bill of Rights is ratified; it says nothing about who may vote (1791).", "Se ratifica la Carta de Derechos; no dice nada de quién puede votar (1791)."),
                       t("The Fifteenth Amendment bans denying the vote by race or color (1870).", "La Decimoquinta Enmienda prohíbe negar el voto por raza o color (1870)."),
                       t("The Nineteenth Amendment bans denying the vote by sex (1920).", "La Decimonovena Enmienda prohíbe negar el voto por sexo (1920)."),
                       t("The Twenty-fourth Amendment bans the poll tax in federal elections (1964).", "La Vigesimocuarta Enmienda prohíbe el impuesto electoral en las elecciones federales (1964)."),
                       t("Congress passes the Voting Rights Act to enforce the Fifteenth (1965).", "El Congreso aprueba la Ley del Derecho al Voto para hacer cumplir la Decimoquinta (1965)."),
                       t("The Twenty-sixth Amendment sets the voting age at 18 (1971).", "La Vigesimosexta Enmienda fija la edad para votar en 18 años (1971).")],
             "inicio": [3, 5, 1, 4, 0, 2],
             "cons": {"4>1": t("A law to enforce the Fifteenth can only come after the Fifteenth.", "Una ley para hacer cumplir la Decimoquinta solo puede llegar después de la Decimoquinta.")},
             "general": t("1791, 1870, 1920, 1964, 1965, 1971.", "1791, 1870, 1920, 1964, 1965, 1971.")}]


def practica():
    A = {"en": ["which-amendment", "liberty-or-right", "timeline"], "es": ["que-enmienda", "libertad-o-derecho", "cronologia"]}[C.L]
    mods = [
        (A[0], t("Which amendment protects you?", "¿Qué enmienda le protege?"), C.om("m1", t("Read the situation and choose the amendment. Remember the pattern: 1 to 3 daily life, 4 to 8 a court case, 9 and 10 how to read the others.", "Lea la situación y elija la enmienda. Recuerde el patrón: de la 1 a la 3, la vida diaria; de la 4 a la 8, un caso ante los tribunales; la 9 y la 10, cómo leer las demás."))),
        (A[1], t("Civil liberty or civil right?", "¿Libertad civil o derecho civil?"), C.clasifica("m2", t("Ask what is being asked for: that the government stop, or equal treatment. If something is not right, the situations marked in yellow get a hint.", "Pregúntese qué se pide: que el gobierno se detenga, o un trato igual. Si algo no está bien, las situaciones marcadas en amarillo reciben una pista."))),
        (A[2], t("Who could vote, and since when", "Quién podía votar, y desde cuándo"), C.orden("m3")),
    ]
    js = (C.js_datos("ENM", banco_enmiendas()) + C.js_datos("LIB", casos_lib()) + C.js_datos("VOTO", casos_orden()) +
          'creaBanco("m1", ENM);\ncreaClasifica("m2", LIB);\ncreaOrden("m3", VOTO);\n')
    return C.pagina_practica(N, titulo(), t("Three activities · the order of the exercises changes every time · two tries in each one", "Tres actividades · el orden de los ejercicios cambia cada vez · dos intentos en cada uno"), mods, js)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
